import math

def count_divisors(n):
    """Calculates tau(n), the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def solve_search():
    min_a = float('inf')

    # We search for n < 1000. Since d(n) must be non-negative, tau(n) >= 2, so n >= 2.
    limit = 1000

    print(f"Starting search for n from 2 up to {limit-1}...")

    for n in range(2, limit):
        n_plus_735 = n + 735

        tau_n = count_divisors(n)
        tau_n_plus_735 = count_divisors(n_plus_735)

        if tau_n == tau_n_plus_735:
            # We found a match. Calculate a.
            a = tau_n - 2

            # Since we are iterating n in increasing order, 
            # a might not be strictly increasing, but we track the minimum.
            if a < min_a:
                min_a = a
                print(f"Match found: n={n}, n+735={n_plus_735}. tau(n) = tau(n+735) = {tau_n}. a = {a}")

    if min_a != float('inf'):
        print(f"\nMinimum a found in the range n < 1000 is: {min_a}")
    else:
        print("\nNo match found in the range n < 1000.")

solve_search()

def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0:
            return False
    return True

def find_prime_pairs(N_limit):
    solutions = []
    print("Searching for prime pairs (n, n+735) up to n =", N_limit)
    for n in range(2, N_limit + 1):
        if is_prime(n):
            n_plus_735 = n + 735
            if is_prime(n_plus_735):
                solutions.append((n, n_plus_735))
    return solutions

# Test up to a reasonably small limit first.
# 735 is relatively large, so primes might be sparse.
limit = 10000

prime_pairs = find_prime_pairs(limit)

if prime_pairs:
    print(f"Found prime pairs (a=0 solution): {prime_pairs}")
else:
