def tau(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

def find_n(a, max_n):
    for n in range(2, max_n):
        if tau(n) - 2 == a and tau(n + 735) - 2 == a:
            return n
    return None

for a in range(3):
    print(f"Checking a={a}...")
    result = find_n(a, 100000)
    if result:
        print(f"Found n={result} for a={a}")
    else:
        print(f"No n found for a={a} up to 100,000")

import math

def get_tau(n):
    tau = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            tau += 1
            if i*i != n:
                tau += 1
    return tau

def get_d(n):
    if n == 1:
        return 0
    return get_tau(n) - 2

for n in range(1, 2000):
    d_n = get_d(n)
    d_n_plus_735 = get_d(n + 735)
    if d_n == d_n_plus_735:
        print(f"n={n}, d(n)={d_n}, d(n+735)={d_n_plus_735}")
